MOD = 998244353

def count_partitions(tree, leaf_set, memo):
    if not leaf_set:
        return 1
    if leaf_set in memo:
        return memo[leaf_set]

    result = 0
    for subset in get_subsets(leaf_set):
        if subset:
            complement = leaf_set - subset
            if all(not is_connected(tree, subset) or not is_connected(tree, complement) for _ in range(10)):
                result = (result + count_partitions(tree, subset, memo) * count_partitions(tree, complement, memo)) % MOD

    memo[leaf_set] = result
    return result

def get_subsets(leaf_set):
    n = len(leaf_set)
    subsets = []
    for i in range(1, 1 << n):
        subset = set()
        for j in range(n):
            if i & (1 << j):
                subset.add(leaf_set[j])
        subsets.append(subset)
    return subsets

def is_connected(tree, subset):
    if not subset:
        return True
    start = next(iter(subset))
    visited = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            stack.extend(tree[node] - visited)
    return len(visited) == len(subset)

def main():
    n = int(input())
    parents = list(map(int, input().split()))

    tree = {i: set() for i in range(1, n + 1)}
    leaves = set()

    for i in range(2, n + 1):
        tree[parents[i - 2]].add(i)
        if len(tree[i]) == 0:
            leaves.add(i)

    memo = {}
    result = count_partitions(tree, leaves, memo)
    print(result)

if __name__ == "__main__":
    main()
